import { ChangeDetectionStrategy, Component, ElementRef, EventEmitter, HostListener, Output, ViewChild, effect, input, signal } from '@angular/core';

export interface HisHopeCommand { id: string; label: string; description?: string; keywords?: string[]; disabled?: boolean; }

@Component({
  selector: 'hh-command-palette',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (open()) {
      <div class="hh-command-backdrop" (click)="close()"></div>
       <section #panel class="hh-command" role="dialog" aria-modal="true" [attr.aria-labelledby]="titleId">
         <h2 [id]="titleId" class="hh-visually-hidden">Command palette</h2>
        <input #queryInput type="search" [value]="query()" (input)="query.set($any($event.target).value)" placeholder="Search commands..." aria-label="Search commands" autofocus />
        <div role="listbox" aria-label="Commands">
          @for (command of filteredCommands(); track command.id) {
            <button type="button" role="option" [disabled]="command.disabled" (click)="choose(command)">
              <strong>{{ command.label }}</strong>
              @if (command.description) { <small>{{ command.description }}</small> }
            </button>
          } @empty { <p class="hh-command__empty">No commands found.</p> }
        </div>
      </section>
    }
  `,
  styles: [`
    :host { display: contents; }
    .hh-command-backdrop { position: fixed; inset: 0; z-index: 1300; background: rgba(15,35,25,.42); }
    .hh-command { position: fixed; top: 12vh; left: 50%; z-index: 1310; width: min(620px, calc(100vw - 32px)); transform: translateX(-50%); overflow: hidden; border: 1px solid var(--border-strong); border-radius: var(--radius-card); background: var(--surface-white); box-shadow: var(--shadow-dialog); }
    .hh-command > input { width: 100%; min-height: 56px; border: 0; border-bottom: 1px solid var(--border-default); padding: 0 18px; background: transparent; color: var(--text-primary); font: inherit; outline: 0; }
    .hh-command [role=listbox] { max-height: 52vh; overflow: auto; padding: 8px; }
    .hh-command button { display: grid; width: 100%; gap: 2px; min-height: 52px; border: 0; border-radius: var(--radius-button); padding: 10px 12px; background: transparent; color: var(--text-primary); text-align: left; font: inherit; cursor: pointer; }
    .hh-command button:hover, .hh-command button:focus-visible { background: var(--surface-hover); outline: 0; }
    .hh-command small, .hh-command__empty { color: var(--text-secondary); font-size: var(--font-size-caption); }
    .hh-command__empty { padding: 20px; text-align: center; }
    .hh-visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
  `],
})
export class HisHopeCommandPaletteComponent {
  readonly titleId = `hh-command-title-${Math.random().toString(36).slice(2)}`;
  readonly commands = input<HisHopeCommand[]>([]);
  readonly open = input(false);
  @Output() readonly selected = new EventEmitter<HisHopeCommand>();
  @Output() readonly closed = new EventEmitter<void>();
  readonly query = signal('');
  @ViewChild('panel') private panel?: ElementRef<HTMLElement>;
  private previousFocus: HTMLElement | null = null;
  constructor() { effect(() => { if (this.open()) { this.previousFocus = typeof document === 'undefined' ? null : document.activeElement as HTMLElement; setTimeout(() => this.panel?.nativeElement.querySelector<HTMLElement>('input,button')?.focus()); } }); }
  filteredCommands(): HisHopeCommand[] { const q = this.query().trim().toLowerCase(); return this.commands().filter(c => !q || [c.label, c.description, ...(c.keywords ?? [])].join(' ').toLowerCase().includes(q)); }
  choose(command: HisHopeCommand): void { if (!command.disabled) { this.selected.emit(command); this.close(); } }
  close(): void { this.query.set(''); this.closed.emit(); setTimeout(() => this.previousFocus?.focus()); }
  @HostListener('document:keydown.escape') onEscape(): void { if (this.open()) this.close(); }
  @HostListener('document:keydown.tab', ['$event']) onTab(event: KeyboardEvent): void { if (!this.open() || !this.panel) return; const focusables = Array.from(this.panel.nativeElement.querySelectorAll<HTMLElement>('input,button,[tabindex]:not([tabindex="-1"])')); if (!focusables.length) return; const first = focusables[0]; const last = focusables[focusables.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); } }
}

import { ChangeDetectionStrategy, Component, ContentChildren, Directive, EventEmitter, QueryList, TemplateRef, Output, effect, input, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HostListener } from '@angular/core';
import { HisHopeBulkAction, HisHopeBulkActionRequest, HisHopePageQuery, HisHopeTableEditSaveRequest, HisHopeTableEditState, HisHopeTableEditor, HisHopeTableEditorOption, HisHopeTableExportFormat, HisHopeTableExportRequest, HisHopeTableSelectionScope, HisHopeTableSelectionState } from '../contracts/his-hope-ui-contracts';

export type HisHopeDataTableDensity = 'comfortable' | 'compact';
export type HisHopeDataTableSortDirection = 'asc' | 'desc';
export interface HisHopeDataTableColumn {
  key: string;
  label: string;
  sortable?: boolean;
  editable?: boolean;
  editor?: HisHopeTableEditor;
  options?: HisHopeTableEditorOption[];
  editValidator?: (value: unknown, row: Record<string, unknown>) => string | null;
  width?: string;
  minWidth?: number;
  maxWidth?: number;
  reorderable?: boolean;
  hideable?: boolean;
  align?: 'start' | 'center' | 'end';
}
export interface HisHopeDataTableSort {
  key: string;
  direction: HisHopeDataTableSortDirection;
}
export type HisHopeDataTableMode = 'client' | 'server';

@Directive({ selector: 'ng-template[hhDataTableCell]', standalone: true })
export class HisHopeDataTableCellDirective {
  constructor(readonly template: TemplateRef<unknown>) {}
  key = input.required<string>({ alias: 'hhDataTableCell' });
}

@Component({
  selector: 'hh-data-table',
  standalone: true,
  imports: [CommonModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <section class="hh-data-table" [class.hh-data-table--compact]="density() === 'compact'"
             [attr.aria-label]="label()" [attr.aria-busy]="loading()">
      @if (loading()) {
        <div class="hh-data-table__state" role="status" aria-live="polite">
          <span class="hh-spinner" aria-hidden="true"></span>
          <p>{{ loadingMessage() }}</p>
        </div>
      } @else if (error()) {
        <div class="hh-data-table__state hh-data-table__state--error" role="alert">
          <span class="material-icons" aria-hidden="true">error_outline</span>
          <p>{{ error() }}</p>
          <button type="button" class="hh-button hh-button--secondary" (click)="retry.emit()">{{ retryLabel() }}</button>
        </div>
      } @else if (configuredColumns().length > 0) {
        <div class="hh-data-table__toolbar">
          <span class="hh-data-table__selection" aria-live="polite">{{ selectionCount() }} selected</span>
          @if (exportable()) {
            <label class="hh-data-table__export">Export as
              <select [value]="exportFormat()" (change)="changeExportFormat($event)" aria-label="Export format">
                @for (format of exportFormats(); track format) { <option [value]="format">{{ format.toUpperCase() }}</option> }
              </select>
            </label>
            <button type="button" class="hh-button hh-button--secondary hh-button--small" (click)="requestExport()">Export</button>
          }
          @if (hasSelection() && bulkActions().length) {
            <div class="hh-data-table__bulk-actions" role="group" aria-label="Bulk actions">
              @for (action of bulkActions(); track action.id) { <button type="button" class="hh-button hh-button--secondary hh-button--small" [disabled]="action.disabled" (click)="runBulkAction(action)">{{ action.label }}</button> }
            </div>
          }
          <details class="hh-data-table__columns">
            <summary>Columns</summary>
            <div class="hh-data-table__columns-menu">
              @for (column of configuredColumns(); track column.key) {
                @if (column.hideable !== false) {
                  <label><input type="checkbox" [checked]="isColumnVisible(column.key)" (change)="toggleColumn(column.key)" /> {{ column.label }}</label>
                }
              }
            </div>
          </details>
        </div>
        @if (!rows().length) {
          <div class="hh-data-table__state" role="status"><span class="material-icons" aria-hidden="true">{{ emptyIcon() }}</span><p>{{ emptyMessage() }}</p></div>
        } @else {
          <div class="hh-data-table__content">
            <table>
              <caption class="hh-visually-hidden">{{ label() }}</caption>
              <thead><tr>
                @if (selection()) { <th scope="col" class="hh-data-table__select"><input type="checkbox" [checked]="allVisibleSelected()" (change)="toggleAll()" aria-label="Select all rows" /></th> }
                @for (column of visibleColumns(); track column.key) {
                  <th scope="col" [style.text-align]="column.align ?? 'start'" [style.width.px]="columnWidth(column)" [attr.draggable]="column.reorderable !== false" (dragstart)="beginColumnDrag(column.key)" (dragover)="$event.preventDefault()" (drop)="dropColumn(column.key)">
                    @if (column.sortable) {
                        <button type="button" class="hh-data-table__sort" (click)="sortBy(column.key)" [attr.aria-label]="'Sort by ' + column.label" [attr.aria-pressed]="sortState()?.key === column.key">
                        {{ column.label }} <span class="hh-data-table__sort-icon" aria-hidden="true">{{ sortIcon(column.key) }}</span>
                      </button>
                    } @else { {{ column.label }} }
                    @if (column.reorderable !== false) {
                      <button type="button" class="hh-data-table__resize" [attr.aria-label]="'Resize ' + column.label + ' column'" (pointerdown)="beginColumnResize($event, column)" (keydown.arrowleft)="resizeByKeyboard($any($event), column, -8)" (keydown.arrowright)="resizeByKeyboard($any($event), column, 8)"></button>
                    }
                  </th>
                }
                @if (inlineEdit()) { <th scope="col" class="hh-data-table__edit-actions">Edit</th> }
              </tr></thead>
              <tbody>
                @for (row of pagedRows(); track rowKeyValue(row)) {
                  <tr [class.hh-data-table__row--clickable]="rowClickable()" [attr.tabindex]="rowClickable() ? 0 : null" [attr.role]="rowClickable() ? 'button' : null" (click)="onRowClick(row)" (keydown.enter)="onRowClick(row)" (keydown.space)="$event.preventDefault(); onRowClick(row)" [attr.aria-label]="rowClickable() ? 'Open row ' + rowKeyValue(row) : null">
                    @if (selection()) { <td class="hh-data-table__select"><input type="checkbox" [checked]="isSelected(row)" (change)="toggleRow(row)" [attr.aria-label]="'Select row ' + rowKeyValue(row)" /></td> }
                    @for (column of visibleColumns(); track column.key) {
                      <td [style.text-align]="column.align ?? 'start'">
                        @if (isEditing(row) && column.editable) {
                          @switch (column.editor ?? 'text') {
                            @case ('select') {
                              <select class="hh-data-table__edit-input" [value]="draftValue(column.key)" (change)="updateDraft(column.key, $event)" [attr.aria-label]="'Edit ' + column.label" [attr.aria-invalid]="editError(column.key) ? 'true' : null">
                                @for (option of column.options ?? []; track option.value) { <option [value]="option.value" [disabled]="option.disabled">{{ option.label }}</option> }
                              </select>
                            }
                            @case ('date') { <input type="date" class="hh-data-table__edit-input" [value]="draftValue(column.key)" (input)="updateDraft(column.key, $event)" [attr.aria-label]="'Edit ' + column.label" [attr.aria-invalid]="editError(column.key) ? 'true' : null" /> }
