import { Injectable, inject } from '@angular/core';
import { HisHopeAuditFeedback } from '../contracts/his-hope-ui-contracts';
import { HisHopeToastService } from '../ui/his-hope-toast.service';

@Injectable({ providedIn: 'root' })
export class HisHopeAuditFeedbackService {
  private readonly toast = inject(HisHopeToastService);

  report(feedback: HisHopeAuditFeedback): void {
    const message = feedback.message ?? `${feedback.action} ${feedback.resource}`;
    if (feedback.outcome === 'failure') this.toast.error(message);
    else if (feedback.outcome === 'success') this.toast.success(message);
    else this.toast.info(message);
  }
}

import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { Injectable, PLATFORM_ID, inject, signal } from '@angular/core';
import { HisHopeTranslationDictionary } from '../contracts/his-hope-ui-contracts';
import { hisHopeEn } from './dictionaries/en';
import { hisHopeViVN } from './dictionaries/vi-vn';

export type HisHopeLocale = string;

@Injectable({ providedIn: 'root' })
export class HisHopeI18nService {
  readonly locale = signal<HisHopeLocale>('vi-VN');
  private dictionary: HisHopeTranslationDictionary = hisHopeViVN;
  private readonly document = inject(DOCUMENT);
  private readonly platformId = inject(PLATFORM_ID);

  readonly dictionaries: Record<string, HisHopeTranslationDictionary> = {
    'vi-VN': hisHopeViVN,
    en: hisHopeEn,
  };

  constructor() { this.restore(); }

  setLocale(locale: HisHopeLocale): void {
    const dictionary = this.dictionaries[locale];
    if (!dictionary) return;
    this.locale.set(locale);
    this.dictionary = dictionary;
    this.applyDocumentLocale(locale);
    if (isPlatformBrowser(this.platformId)) localStorage.setItem('hh-locale', locale);
  }

  registerLocale(locale: HisHopeLocale, dictionary: HisHopeTranslationDictionary): void {
    this.dictionaries[locale] = dictionary;
  }

  restore(): void {
    if (!isPlatformBrowser(this.platformId)) return;
    const stored = localStorage.getItem('hh-locale');
    const documentLocale = this.document.documentElement.lang;
    const locale = stored && this.dictionaries[stored]
      ? stored
      : documentLocale.toLowerCase().startsWith('en') ? 'en' : 'vi-VN';
    this.setLocale(locale);
  }

  configure(locale: string, dictionary?: HisHopeTranslationDictionary): void {
    if (dictionary) {
      this.locale.set(locale as HisHopeLocale);
      this.dictionary = dictionary;
      this.applyDocumentLocale(locale);
      return;
    }
    if (this.dictionaries[locale]) this.setLocale(locale);
  }

  t(key: string, fallback = key, params: Record<string, string | number> = {}): string {
    const value = key.split('.').reduce<unknown>((current, part) => current && typeof current === 'object' ? (current as HisHopeTranslationDictionary)[part] : undefined, this.dictionary);
    return Object.entries(params).reduce((result, [name, replacement]) => result.replaceAll(`{{${name}}}`, String(replacement)), typeof value === 'string' ? value : fallback);
  }

  private applyDocumentLocale(locale: HisHopeLocale): void {
    if (!isPlatformBrowser(this.platformId)) return;
    this.document.documentElement.lang = locale;
    this.document.documentElement.dataset['locale'] = locale;
  }
}

import { DOCUMENT, isPlatformBrowser } from '@angular/common';
import { Injectable, PLATFORM_ID, inject, signal } from '@angular/core';

export type HisHopeTheme = 'light' | 'dark' | 'system';
export type HisHopeResolvedTheme = 'light' | 'dark';

@Injectable({ providedIn: 'root' })
export class HisHopeThemeService {
  private readonly document = inject(DOCUMENT);
  private readonly platformId = inject(PLATFORM_ID);
  readonly theme = signal<HisHopeTheme>('system');
  readonly resolvedTheme = signal<HisHopeResolvedTheme>('light');
  readonly highContrast = signal(false);
  private systemMediaQuery?: MediaQueryList;

  constructor() {
    if (isPlatformBrowser(this.platformId)) {
      this.systemMediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
      this.systemMediaQuery.addEventListener('change', () => {
        if (this.theme() === 'system') this.applyThemeAttribute('system');
      });
    }
    this.restore();
  }

  setTheme(theme: HisHopeTheme): void {
    this.theme.set(theme);
    if (!isPlatformBrowser(this.platformId)) return;
    this.applyThemeAttribute(theme);
    localStorage.setItem('hh-theme', theme);
  }

  setHighContrast(enabled: boolean): void {
    this.highContrast.set(enabled);
    if (!isPlatformBrowser(this.platformId)) return;
    this.applyContrastAttribute(enabled);
    localStorage.setItem('hh-contrast', String(enabled));
  }

  restore(): void {
    if (!isPlatformBrowser(this.platformId)) return;
    const storedTheme = localStorage.getItem('hh-theme') as HisHopeTheme | null;
    const storedContrast = localStorage.getItem('hh-contrast');
    this.theme.set(storedTheme === 'light' || storedTheme === 'dark' || storedTheme === 'system' ? storedTheme : 'system');
    this.highContrast.set(storedContrast === 'true');
    this.applyThemeAttribute(this.theme());
    this.applyContrastAttribute(this.highContrast());
  }

  private applyThemeAttribute(theme: HisHopeTheme): void {
    const root = this.document.documentElement;
    const resolvedTheme: HisHopeResolvedTheme = theme === 'system'
      ? (this.systemMediaQuery?.matches ? 'dark' : 'light')
      : theme;
    this.resolvedTheme.set(resolvedTheme);
    root.dataset['theme'] = resolvedTheme;
    root.dataset['themeMode'] = theme;
  }

  private applyContrastAttribute(enabled: boolean): void {
    if (enabled) this.document.documentElement.dataset['contrast'] = 'high';
    else this.document.documentElement.removeAttribute('data-contrast');
  }
}

