:host { display: block; color: var(--text-primary); font-family: var(--font-sans); }
.brand { display: flex; align-items: center; gap: 10px; }
.brand-mark {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 9px;
  background: var(--color-primary);
  color: #fff;
  flex: 0 0 auto;
}
.brand-mark::before,
.brand-mark::after,
.brand-mark span {
  content: '';
  position: absolute;
  display: block;
  border-radius: 2px;
  background: #fff;
}
