.brand-name { font-size: 18px; font-weight: 700; letter-spacing: 0; }
.brand-caption {
  margin: 12px 0 0;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .12em;
  line-height: 1.3;
  text-transform: uppercase;
}

