  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <section class="hh-page-section" [attr.aria-labelledby]="titleId()">
      <header class="hh-page-section__header">
        <div>
          <h2 [id]="titleId()">{{ title() }}</h2>
          @if (subtitle()) { <p>{{ subtitle() }}</p> }
